from six import with_metaclass
from abc import ABCMeta
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.api.default_api import DefaultApi
from taf.internal.sw.dcap.rd.client.dcap_lite.v3 import ApiClient, Configuration
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.bts_login_with_optional_credentials import \
    BTSLoginWithOptionalCredentials
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.api.content_type_file_api import ContentTypeFileApi
from taf.sw.dcap.rd.services.custom_traces.bts_custom_profile import CustomBTSTraceProfile
from taf.sw.dcap.rd.services.custom_traces.gnb_custom_profile import Custom5gTraceProfile
from taf.sw.dcap.rd.services.custom_traces.enb_custom_profile import CustomLteTraceProfile
from taf.sw.dcap.rd.services.custom_traces.vcu_custom_profile import CustomVcuTraceProfile
from taf.sw.dcap.rd.services.custom_traces.vdu_custom_profile import CustomVduTraceProfile
import time
import shutil
import os
import tempfile
from taf.sw.dcap.rd.log_request_response import log_request_response

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


def get_config_details(con_details):
    conf = Configuration()
    conf.verify_ssl = False
    conf.api_key_prefix['key'] = 'Bearer'
    conf.host = con_details.make_configuration_host(original_endpoint=conf.host)
    return conf


class CM(with_metaclass(ABCMeta, object)):
    def __init__(self, con_details):
        conf = get_config_details(con_details)

        api_client = ApiClient(configuration=conf)
        api_client.request = log_request_response(api_client.request)
        self.api_client = DefaultApi(api_client)

        self.content_type_file_api = ContentTypeFileApi(api_client)
        self._create_bts = None
        self._start_trace_body = None
        self._bts_login = None

    def wait_for_start_trace_activation(self, wait_for_activation=False, timeout=400):
        if wait_for_activation:
            self._wait_for_statuses(trace_id=self._start_trace_body.id, timeout=timeout,
                                    expected_statuses=['running', 'runningWithWarnings',
                                                       'ready', 'readyWithWarnings', ])
            return self.get_trace_info_by_id(self._start_trace_body.id, timeout)
        return self._start_trace_body

    def get_5g_trace_profile_info(self, gnb_trace_profile, timeout):
        profiles = self.get_5g_profiles(timeout)
        for profile in profiles:
            try:
                if profile.id == gnb_trace_profile or profile.name == gnb_trace_profile:
                    return profile
            except ValueError:
                logger.info("There are no 5g profiles matching with either id or name, please check")

    def get_lte_trace_profile_info(self, enb_trace_profile, timeout):
        profiles = self.get_lte_profiles(timeout)

        for profile in profiles:
            try:
                if profile.id == enb_trace_profile or profile.name == enb_trace_profile:
                    return profile
            except ValueError:
                logger.info("There are no lte profiles matching with either id or name, please check")

    def get_vcu_profiles(self, timeout):
        return self.api_client.get_profiles_vcu_v2(_request_timeout=timeout)

    def get_vcu_trace_profile_info(self, vcu_trace_profile, timeout):
        profiles = self.get_vcu_profiles(timeout=timeout)
        for profile in profiles:
            try:
                if profile.id == vcu_trace_profile or profile.name == vcu_trace_profile:
                    return profile
            except ValueError:
                logger.info("There are no vcu profiles matching with either id or name, please check")

    def get_vdu_profiles(self, timeout):
        return self.api_client.get_profiles_vdu_v2(_request_timeout=timeout)

    def get_vdu_trace_profile_info(self, vdu_trace_profile, timeout):
        profiles = self.get_vdu_profiles(timeout=timeout)
        for profile in profiles:
            try:
                if profile.id == vdu_trace_profile or profile.name == vdu_trace_profile:
                    return profile
            except ValueError:
                logger.info("There are no vdu profiles matching with either id or name, please check")

    @staticmethod
    def start_trace_profile(**kwargs):
        li = []
        for value in kwargs.values():
            if value is not None:
                li.append(value)
        if li.__len__() > 1:
            return li
        return li[0]

    def get_bts_profiles(self, timeout):
        return self.api_client.get_profiles_bts_v2(_request_timeout=timeout)

    def get_bts_trace_profile_info(self, bts_trace_profile):
        profiles = self.get_bts_profiles(timeout=30)
        for profile in profiles:
            try:
                if profile.id == bts_trace_profile or profile.name == bts_trace_profile:
                    return profile
            except ValueError:
                logger.info("There are no bts profiles matching with either id or name, please check")

    def gnb_trace_custom_selection(self, **kwargs):
        if kwargs.get('gnb_trace_profile'):
            return self.get_5g_trace_profile_info(kwargs.get('gnb_trace_profile'), kwargs.get('timeout'))
        elif kwargs.get('gnb_custom_profile'):
            return {'id': 'dcap-lite-custom', 'name': 'Custom Profile',
                    'tracers': Custom5gTraceProfile(requirements=kwargs.get('gnb_custom_profile'),
                                                    **kwargs).custom_trace_profile}

    def bts_trace_custom_selection(self, **kwargs):
        if kwargs.get('bts_trace_profile'):
            return self.get_bts_trace_profile_info(bts_trace_profile=kwargs.get('bts_trace_profile'))
        elif kwargs.get('bts_custom_profile'):
            return {'id': 'dcap-lite-custom', 'name': 'Custom Profile',
                    'tracers': CustomBTSTraceProfile
                    (requirements=kwargs.get('bts_custom_profile'), **kwargs).custom_trace_profile}

    def vcu_trace_custom_selection(self, **kwargs):
        if kwargs.get('vcu_trace_profile'):
            return self.get_vcu_trace_profile_info(vcu_trace_profile=kwargs.get('vcu_trace_profile'),
                                                   timeout=kwargs.get('timeout'))
        elif kwargs.get('vcu_custom_profile'):
            return {'id': 'dcap-lite-custom', 'name': 'Custom Profile',
                    'tracers': CustomVcuTraceProfile
                    (requirements=kwargs.get('vcu_custom_profile'),
                     **kwargs).custom_trace_profile}

    def vdu_trace_custom_selection(self, **kwargs):
        if kwargs.get('vdu_trace_profile'):
            return self.get_vdu_trace_profile_info(vdu_trace_profile=kwargs.get('vdu_trace_profile'),
                                                   timeout=kwargs.get('timeout'))
        elif kwargs.get('vdu_custom_profile'):
            return {'id': 'dcap-lite-custom', 'name': 'Custom Profile',
                    'tracers': CustomVduTraceProfile
                    (requirements=kwargs.get('vdu_custom_profile'),
                     **kwargs).custom_trace_profile}

    def enb_trace_custom_selection(self, **kwargs):
        if kwargs.get('enb_trace_profile'):
            return self.get_lte_trace_profile_info(kwargs.get('enb_trace_profile'), kwargs.get('timeout'))
        elif kwargs.get('enb_custom_profile'):
            return {'id': 'dcap-lite-custom', 'name': 'Custom Profile',
                    'tracers': CustomLteTraceProfile(requirements=kwargs.get('enb_custom_profile'),
                                                     **kwargs).custom_trace_profile}

    def start_gnb_lte_trace_profiles(self, **kwargs):
        gnb_trace_profile = self.gnb_trace_custom_selection(**kwargs)
        bts_trace_profile = self.bts_trace_custom_selection(**kwargs)
        vcu_trace_profile = self.vcu_trace_custom_selection(**kwargs)
        vdu_trace_profile = self.vdu_trace_custom_selection(**kwargs)
        enb_trace_profile = self.enb_trace_custom_selection(**kwargs)
        trace_profiles = self.start_trace_profile(gnb_trace_profile=gnb_trace_profile,
                                                  enb_trace_profile=enb_trace_profile,
                                                  bts_trace_profile=bts_trace_profile,
                                                  vcu_trace_profile=vcu_trace_profile,
                                                  vdu_trace_profile=vdu_trace_profile)
        return trace_profiles

    @staticmethod
    def _trace_profile_dict_info(trace_profiles, tracers):
        trace_profile_dict = eval(tracers)
        for profile in trace_profile_dict:
            profile['params'] = [eval(d) for d in profile['params']]
        tracers_dict = {'tracers': trace_profile_dict}
        trace_profiles.update(tracers_dict)
        return trace_profiles

    @staticmethod
    def _get_gnb_or_lte_tracers(gnb_lte_trace_profiles):
        trace_profiles = {'id': gnb_lte_trace_profiles.__getattribute__('id'),
                          'name': gnb_lte_trace_profiles.__getattribute__('name')}
        tracers = str(gnb_lte_trace_profiles.__getattribute__('tracers'))
        return CM._trace_profile_dict_info(trace_profiles, tracers)

    @staticmethod
    def _get_and_gnb_lte_tracers_info_common(gnb_lte_trace_profiles, tracer_id):
        trace_profiles_info = {'id': gnb_lte_trace_profiles[tracer_id].__getattribute__('id'),
                               'name': gnb_lte_trace_profiles[tracer_id].__getattribute__('name')}
        tracers = str(gnb_lte_trace_profiles[tracer_id].__getattribute__('tracers'))
        trace_profiles = CM._trace_profile_dict_info(trace_profiles_info, tracers)
        return trace_profiles

    @staticmethod
    def _get_and_gnb_lte_tracers_info(gnb_lte_trace_profiles):
        gnb_lte_tracers = []
        for i in range(0, len(gnb_lte_trace_profiles)):
            trace_profiles = CM._get_and_gnb_lte_tracers_info_common(gnb_lte_trace_profiles=gnb_lte_trace_profiles,
                                                                     tracer_id=i)
            gnb_lte_tracers.append(trace_profiles)
        return gnb_lte_tracers

    @staticmethod
    def _get_gnb_or_lte_custom_tracers(gnb_lte_trace_profiles):
        custom_profile = []
        for custom_trace in gnb_lte_trace_profiles.get('tracers'):
            tracers_info_dict = {'providedTraces': custom_trace.provided_traces, 'id': custom_trace.id,
                                 'name': custom_trace.name, 'type': custom_trace.type, 'params': custom_trace.params}
            custom_profile.append(tracers_info_dict)
        trace_profiles = {'id': gnb_lte_trace_profiles.get('id'), 'name': gnb_lte_trace_profiles.get('name'),
                          'tracers': custom_profile}
        return trace_profiles

    @staticmethod
    def _get_gnb_and_lte_custom_tracers_info(gnb_lte_trace_profiles):
        custom_profile = []
        gnb_lte_custom = []
        for i in range(0, len(gnb_lte_trace_profiles)):
            for custom_trace in gnb_lte_trace_profiles[i].get('tracers'):
                tracers_info_dict = {'providedTraces': custom_trace.provided_traces, 'id': custom_trace.id,
                                     'name': custom_trace.name, 'type': custom_trace.type,
                                     'params': custom_trace.params}
                custom_profile.append(tracers_info_dict)
        trace_profiles = {'id': gnb_lte_trace_profiles[i]['id'], 'name': gnb_lte_trace_profiles[i]['name'],
                          'tracers': custom_profile}
        gnb_lte_custom.append(trace_profiles)
        return gnb_lte_custom

    @staticmethod
    def _get_lte_custom_tracers(gnb_lte_trace_profiles):
        custom_profile = []
        for custom_trace in gnb_lte_trace_profiles.get('tracers'):
            tracers_info_dict = {'providedTraces': custom_trace[0].__getattribute__('provided_traces'),
                                 'id': custom_trace[0].__getattribute__('id'),
                                 'name': custom_trace[0].__getattribute__('name'),
                                 'type': custom_trace[0].__getattribute__('type'),
                                 'params': custom_trace[0].__getattribute__('params')}
            custom_profile.append(tracers_info_dict)
        trace_profiles = {'id': gnb_lte_trace_profiles.get('id'), 'name': gnb_lte_trace_profiles.get('name'),
                          'tracers': custom_profile}
        return trace_profiles

    @staticmethod
    def _get_tracers_info_dict(custom_trace):
        return {
            'providedTraces': custom_trace.provided_traces,
            'id': custom_trace.id,
            'name': custom_trace.name,
            'type': custom_trace.type,
            'params': custom_trace.params
        }

    @staticmethod
    def _get_gnb_profile_and_enb_custom_tracers(gnb_lte_trace_profiles):
        gnb_lte_tracers = []
        gnb_lte_custom = []
        for i in range(len(gnb_lte_trace_profiles)):
            try:
                custom_profile = [
                    CM._get_tracers_info_dict(custom_trace)
                    for custom_trace in gnb_lte_trace_profiles[i].get('tracers')
                ]
                trace_profiles = {
                    'id': gnb_lte_trace_profiles[i]['id'],
                    'name': gnb_lte_trace_profiles[i]['name'],
                    'tracers': custom_profile
                }
                gnb_lte_custom.append(trace_profiles)
            except Exception:
                trace_profiles = CM._get_and_gnb_lte_tracers_info_common(gnb_lte_trace_profiles=gnb_lte_trace_profiles,
                                                                         tracer_id=i)
                gnb_lte_tracers.append(trace_profiles)
        return gnb_lte_tracers + gnb_lte_custom

    def start_trace_profile_selection(self, **kwargs):
        gnb_lte_trace_profiles = self.start_gnb_lte_trace_profiles(**kwargs)
        profile_trace_list = ['gnb_trace_profile', 'enb_trace_profile', 'bts_trace_profile', 'vdu_trace_profile',
                              'vcu_trace_profile']
        custom_trace_list = ['gnb_custom_profile', 'enb_custom_profile', 'bts_custom_profile', 'vdu_custom_profile',
                             'vcu_custom_profile']
        custom_count = len(set((kwargs.keys())).intersection(custom_trace_list))
        profile_count = len(set((kwargs.keys())).intersection(profile_trace_list))
        if profile_count > 1 and custom_count == 0:
            trace_profiles = self._get_and_gnb_lte_tracers_info(gnb_lte_trace_profiles)
        elif (profile_count == 0 and custom_count > 1) or (profile_count > 0 and custom_count > 0):
            trace_profiles = self._get_gnb_profile_and_enb_custom_tracers(gnb_lte_trace_profiles)
        elif profile_count == 1 and custom_count == 0:
            trace_profiles = self._get_gnb_or_lte_tracers(gnb_lte_trace_profiles)
        elif profile_count == 0 and custom_count == 1:
            trace_profiles = self._get_gnb_or_lte_custom_tracers(gnb_lte_trace_profiles)
        else:
            raise EnvironmentError("profile or custom name might be wrong, Please check doc link")
        return trace_profiles

    def _wait_for_statuses(self, trace_id, expected_statuses, fail_statuses=None, timeout=700):
        if fail_statuses is None:
            fail_statuses = []
        end_time = time.time() + timeout
        last_status = None
        while time.time() < end_time:
            time.sleep(0.1)
            current_status = self.get_trace_info_by_id(trace_id=trace_id, timeout=timeout).status
            if current_status != last_status:
                logger.debug("state change: %s -> %s", last_status, current_status)
                last_status = current_status
            if current_status in expected_statuses:
                return current_status
            if current_status in fail_statuses:
                raise RuntimeError(
                    "status {current_status!r} in "
                    "fail statuses {fail_statuses} "
                    "for trace_id {trace_id}".format(
                        current_status=current_status,
                        fail_statuses=fail_statuses,
                        trace_id=trace_id))
        else:
            raise RuntimeError(
                "status {current_status!r} not in "
                "expected statuses {expected_statuses} "
                "for trace_id {trace_id} "
                "after {timeout} seconds timeout".format(
                    current_status=current_status,
                    expected_statuses=expected_statuses,
                    trace_id=trace_id,
                    timeout=timeout))

    def _get_trace_id(self, trace_id=None):
        if not trace_id:
            trace_id = self._start_trace_body.id
        return trace_id

    def _get_bts_id(self, bts_id=None):
        if not bts_id:
            bts_id = self._create_bts.id
        return bts_id

    def stop_trace(self, trace_id, timeout):
        trace_id = self._get_trace_id(trace_id)
        current_status = self._wait_for_statuses(
            trace_id=trace_id,
            expected_statuses=['running', 'runningWithWarnings', 'ready'],
            fail_statuses=['notRunning', 'failed', 'failedToStop', 'aborted'],
            timeout=timeout)
        if 'ready' in current_status:
            logger.debug("Trace is already in ready state, Hence skipping stop_trace.")
        else:
            return self.api_client.stop_trace(trace_id=trace_id, _request_timeout=timeout)

    def _raise_run_time_error(self):
        raise RuntimeError(
            "The trace result can only be downloadable if it is in "
            " notRunning, failed, failedToStop, ready, aborted one of these states."
            " Other than this there are some other state's like initializing, starting, running, stopping,"
            " abortStarting, aborting, postProcessing, packaging, abortPackaging."
            " If download fails then it might be in one of these states, please check")

    @staticmethod
    def move_logs_to_target_dir(result_path, target_dir, target_file_name=None):
        if target_dir:
            target_file_name = target_file_name if target_file_name else os.path.basename(result_path)
            target_path = os.path.join(target_dir, target_file_name)
            shutil.move(result_path, target_path)
            return target_path
        return result_path

    def get_results(self, result_id, timeout, target_dir=None, target_file_name=None):
        result_id = self._get_trace_id(trace_id=result_id)
        try:
            self._wait_for_statuses(trace_id=result_id,
                                    expected_statuses=['notRunning', 'failed', 'failedToStop', 'ready',
                                                       'aborted', 'readyWithWarnings'],
                                    timeout=timeout)
            response = self.content_type_file_api.get_results(id=result_id,
                                                              _request_timeout=timeout,
                                                              _preload_content=False)

            if not response or not hasattr(response, 'stream'):
                raise ValueError("Response is not a valid streaming response.")

            if target_dir is None:
                target_dir = tempfile.gettempdir()

            CHUNK_SIZE = 64 * 1024 * 1024

            if target_file_name:
                file_path = os.path.join(target_dir, f"{target_file_name}.zip")
            else:
                start_time_info = self.get_trace_info_by_id(trace_id=result_id, timeout=timeout).start_time
                file_name = start_time_info.replace(":", "_").replace("-", "_").replace(".", "_")
                file_path = os.path.join(target_dir, f"UTFLab_{file_name}.zip")

            with open(file_path, 'wb', buffering=CHUNK_SIZE) as f:
                for chunk in response.stream(CHUNK_SIZE):
                    f.write(chunk)
            return file_path

        except RuntimeError:
            self._raise_run_time_error()

    def get_result_file_contents(self, result_id, timeout):
        result_id = self._get_trace_id(trace_id=result_id)
        try:
            self._wait_for_statuses(trace_id=result_id,
                                    expected_statuses=['notRunning', 'failed', 'failedToStop', 'ready',
                                                       'aborted', 'readyWithWarnings'],
                                    timeout=timeout)
            return self.api_client.get_result_file_contents(id=result_id, _request_timeout=timeout)
        except RuntimeError:
            self._raise_run_time_error()

    def get_result_file(self, file_path_in_zip, result_id, target_dir, timeout, target_file_name=None):
        result_id = self._get_trace_id(trace_id=result_id)
        try:
            self._wait_for_statuses(trace_id=result_id,
                                    expected_statuses=['notRunning', 'failed', 'failedToStop', 'ready',
                                                       'aborted', 'readyWithWarnings'],
                                    timeout=timeout)
            base_dir = target_dir if target_dir else tempfile.gettempdir()
            sub_dir = file_path_in_zip.split('/')[0]
            target_dir = os.path.join(base_dir, sub_dir)
            if not os.path.exists(target_dir):
                os.makedirs(target_dir, exist_ok=True)
            result_path = self.content_type_file_api.get_result_file(file_path_in_zip=file_path_in_zip, id=result_id,
                                                                     _request_timeout=timeout)
            return self.move_logs_to_target_dir(result_path, target_dir, target_file_name)
        except RuntimeError:
            self._raise_run_time_error()

    def delete_bts(self, bts_id, timeout):
        bts_id = self._get_bts_id(bts_id=bts_id)
        return self.api_client.delete_bts(id=bts_id, _request_timeout=timeout)

    def get_all_trace_info(self, timeout):
        return self.api_client.get_all_trace_info_v1(_request_timeout=timeout)

    def edit_bts(self, bts_id, host, port='443', username='Nemuadmin', password='nemuuser', bts_alias='test_run',
                 lte_cells=None, nr_cells=None, timeout=30):
        self._bts_login = BTSLoginWithOptionalCredentials(host=host, port=port, username=username, password=password,
                                                          alias=bts_alias, lte_cells=lte_cells, nr_cells=nr_cells)
        return self.api_client.edit_bts(id=bts_id, bts_login_with_optional_credentials=self._bts_login,
                                        _request_timeout=timeout)

    def delete_trace(self, trace_id, timeout):
        trace_id = self._get_trace_id(trace_id)
        return self.api_client.delete_trace(trace_id=trace_id, _request_timeout=timeout)

    def get_tracers(self, timeout):
        return self.api_client.get_tracers(_request_timeout=timeout)

    def abort_trace(self, trace_id, timeout):
        trace_id = self._get_trace_id(trace_id)
        return self.api_client.abort_trace(trace_id=trace_id, _request_timeout=timeout)
